"use client";

import Image from "next/image";
import Link from "next/link";
import logo from "@/app/assets/logo.png";
import farm from "@/app/assets/farm.jpg";
import { Eye, Mail, Lock } from "lucide-react";
import { useForm } from "react-hook-form";
import { LoginFormData, loginSchema } from "../../_schema/schema";
import { zodResolver } from "@hookform/resolvers/zod";

export default function LoginForm() {
    const {
        register,
        handleSubmit,
        formState: { errors, isSubmitting },
    } = useForm<LoginFormData>({
        resolver: zodResolver(loginSchema),
        defaultValues: {
            email: "",
            password: ""
        }
    });

    const onSubmit = (data: LoginFormData) => {
        console.log(data);
    };

    return (
        <div className="min-h-screen flex">

            {/* LEFT SIDE IMAGE */}
            <div className="hidden md:flex w-1/2 relative bg-green-800 items-center justify-center">

                <div className="absolute inset-0">
                    <Image
                        src={farm}
                        alt="Farm"
                        fill
                        className="object-cover opacity-80"
                    />
                </div>

                {/* decorative circle overlay */}
                <div className="relative z-10 border-4 border-white rounded-full w-[420px] h-[420px] overflow-hidden">
                    <Image
                        src={farm}
                        alt="Farm"
                        fill
                        className="object-cover"
                    />
                </div>
            </div>

            {/* RIGHT SIDE FORM */}
            <div className="w-full md:w-1/2 flex items-center justify-center bg-white px-8">

                <div className="w-full max-w-md">

                    {/* Title */}
                    <h2 className="text-2xl font-bold text-center text-gray-800">
                        Welcome Back
                    </h2>

                    <p className="text-center text-gray-500 mb-6">
                        Login to your account
                    </p>

                    {/* Logo */}
                    <div className="flex justify-center mb-6">
                        <Image src={logo} alt="logo" width={120} height={60} />
                    </div>

                    {/* FORM */}
                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">

                        {/* EMAIL */}
                        <div>
                            <label className="text-sm font-medium">
                                Phone Number / Email
                            </label>

                            <div className="flex items-center border rounded px-3 py-2 mt-1">
                                <Mail className="text-gray-400 mr-2" size={18} />
                                <input
                                    type="text"
                                    placeholder="Enter email or phone"
                                    className="w-full outline-none"
                                    {...register("email")}
                                />
                            </div>

                            {errors.email && (
                                <p className="text-red-500 text-sm">
                                    {errors.email.message}
                                </p>
                            )}
                        </div>

                        {/* PASSWORD */}
                        <div>
                            <label className="text-sm font-medium">Password</label>

                            <div className="flex items-center border rounded px-3 py-2 mt-1">
                                <Lock className="text-gray-400 mr-2" size={18} />
                                <input
                                    type="password"
                                    placeholder="Enter password"
                                    className="w-full outline-none"
                                    {...register("password")}
                                />
                                <Eye className="text-gray-400 cursor-pointer" size={18} />
                            </div>

                            {errors.password && (
                                <p className="text-red-500 text-sm">
                                    {errors.password.message}
                                </p>
                            )}
                        </div>

                        {/* BUTTON */}
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="w-full bg-green-700 hover:bg-green-800 text-white py-2 rounded font-semibold"
                        >
                            {isSubmitting ? "Logging in..." : "LOGIN"}
                        </button>
                    </form>

                    {/* REGISTER */}
                    <p className="text-center mt-6 text-sm">
                        Don’t have an account?{" "}
                        <Link href="/register">
                            <span className="text-red-500 font-semibold cursor-pointer">
                                Register
                            </span>
                        </Link>
                    </p>

                </div>
            </div>
        </div>
    );
}